      end else begin
        cache_rdy[cc] <= 2;
        cache[cc] <= addr;
        cache_v[cc] <= safe_rom[addr];
        cc <= (cc + 1)%2;
    end
    state <= `MSTAGE_2;
    end
    `MSTAGE_2: begin
      regfile[ram[pc][5:4]] <= cache_v[(cc + 1)%2];
      state <= `RDY;
      increment_pc();
    end
    `RDY: begin
          case(ram[pc][3:0]) 
      `ADD: begin
        regfile[ram[pc][5:4]] <=  regfile[ram[pc][7:6]] + regfile[ram[pc+1][1:0]];
        increment_pc();
      end
      `INC: begin
        // $display("INC: R%d %d",ram[pc][5:4],regfile[ram[pc][5:4]]);
        regfile[ram[pc][5:4]] <=  regfile[ram[pc][5:4]] + 1;
        increment_pc();
      end
      `SUB: begin
        regfile[ram[pc][5:4]] <=  regfile[ram[pc][7:6]] -  regfile[ram[pc+1][1:0]];
        // $display("SUB: %d %d", regfile[ram[pc][7:6]] -  regfile[ram[pc+1][1:0]],ram[19]);
        increment_pc();
      end
      `MOVF: begin
        if ( (cache_rdy[0] == 1) && (cache[0] == ram[pc+1]) ) begin
           regfile[ram[pc][5:4]] <= cache_v[0];
           increment_pc();
        end else if ((cache_rdy[1] == 1) && (cache[1] == ram[pc+1])) begin
           regfile[ram[pc][5:4]] <= cache_v[1];
           increment_pc();
        end else begin
           state <= `MSTAGE_1;
           addr <= ram[pc+1];
           is_ram <= 1;
        end
      end
      `RDTM: begin
        regfile[ram[pc][5:4]] <= tck;
        increment_pc();
      end
      `MOVFU: begin
        if ((cache_rdy[0] == 1) && (cache[0] == ram[pc+1])) begin
           regfile[ram[pc][5:4]] <= cache_v[0];
           increment_pc();
        end else if ((cache_rdy[1] == 1) && (cache[1] == ram[pc+1])) begin
           regfile[ram[pc][5:4]] <= cache_v[1];
           increment_pc();
        end else begin
           state <= `DSTAGE_1;
           addr <= ram[pc+1];
           is_ram <= 1;
        end
      end
      `MOVFS: begin
        if(emode) begin 
        if ((cache_rdy[0] == 2) && (cache[0] == safe_rom[pc+1]) ) begin
           regfile[ram[pc][5:4]] <= cache_v[0];
           increment_pc();
        end else if ((cache_rdy[1] == 2) && (cache[1] == safe_rom[pc+1])) begin
           regfile[ram[pc][5:4]] <= cache_v[1];
           increment_pc();
        end else begin
           state <= `MSTAGE_1;
           addr <= ram[pc+1];
           is_ram <= 0;
        end
        end
        increment_pc();
      end
      `MOVFI: begin
        addr = ram[pc+1] + regfile[ram[pc][7:6]];
        is_ram <= 1;
        if ( (cache_rdy[0] == 1) && (cache[0] == addr) ) begin
           regfile[ram[pc][5:4]] <= cache_v[0];
           increment_pc();
        end else if ((cache_rdy[1] == 1) && (cache[1] == addr)) begin
           regfile[ram[pc][5:4]] <= cache_v[1];
           increment_pc();
        end else begin
           state <= `MSTAGE_1;
        end
      end
      `MOVFSI: begin
        if(emode) begin
          addr = safe_rom[pc+1] + regfile[ram[pc][7:6]];
          is_ram <= 1;
          if ( (cache_rdy[0] == 1) && (cache[0] == addr) ) begin
             regfile[ram[pc][5:4]] <= cache_v[0];
             increment_pc();
          end else if ((cache_rdy[1] == 1) && (cache[1] == addr)) begin
             regfile[ram[pc][5:4]] <= cache_v[1];
             increment_pc();
          end else begin
             state <= `MSTAGE_1;
          end
        end else begin
          state <= `LOCKED;
        end
      end
      `MOVT: begin
        if(cache[0] == ram[pc+1]) begin
          cache_rdy[0] <= 0;
        end
        if(cache[1] == ram[pc+1]) begin
          cache_rdy[1] <= 0;
        end
