#!/usr/bin/env python3
def encode_inst(opcode, r1=0, r2=0, r3=0):
    return (r3 << 6) | (r1 << 4) | opcode

def gen_ram(instructions):
    ram = [0] * 256
    for i, (addr, value) in enumerate(instructions):
        ram[addr] = value
    with open('ram.hex', 'w') as f:
        for i in range(0, 256, 16):
            line = ' '.join(f'{x:02x}' for x in ram[i:i+16])
            f.write(line + '\n')

from pwn import *
import time

# Enable debug logging
context.log_level = 'debug'

def setup_connection():
    conn = remote('rev.chal.csaw.io', 8000)
    conn.recvuntil(b'WELCOME')  # Wait for welcome message
    return conn

def measure_access_time(conn, address):
    conn.sendline(f'r {address:x}'.encode())
    start = time.time_ns()
    try:
        resp = conn.recvline()
        end = time.time_ns()
        return end - start
    except EOFError:
        return float('inf')

def flush_cache(conn):
    try:
        for addr in range(0, 0x100, 0x10):
            conn.sendline(f'r {addr:x}'.encode())
            conn.recvline()
    except EOFError:
        return

def train_branch(conn, iterations=6):
    try:
        for _ in range(iterations):
            conn.sendline(b'r 0')
            conn.recvline()
    except EOFError:
        return

def extract_byte(conn, target_addr):
    result_byte = 0
    timings = []

    # Get baseline timing
    flush_cache(conn)
    baseline_timing = measure_access_time(conn, 0xFF)

    for bit in range(8):
        total_timing = 0
        num_samples = 3
        valid_samples = 0

        while valid_samples < num_samples:
            try:
                if not conn.connected():
                    conn = setup_connection()

                flush_cache(conn)
                train_branch(conn)

                # Enter mode and trigger speculation
                conn.sendline(b'mode')
                conn.recvline()

                # Access target byte
                probe_addr = 0xFF
                conn.sendline(f'r {target_addr + (1 << bit):x}'.encode())

                timing = measure_access_time(conn, probe_addr)
                if timing != float('inf'):
                    total_timing += timing
                    valid_samples += 1

            except EOFError:
                conn = setup_connection()
                continue

        avg_timing = total_timing / num_samples
        timings.append(avg_timing)

        # Dynamic threshold based on baseline
        if avg_timing < baseline_timing * 0.8:
            result_byte |= (1 << bit)

    log.info(f'Timings for addr {target_addr:x}: {timings}')
    return result_byte

def main():
    extracted = []
    conn = setup_connection()

    try:
        for addr in range(5):
            log.info(f'Extracting byte at address {addr}')

            # Multiple attempts for reliable extraction
            attempts = 0
            byte = None

            while attempts < 3 and (byte is None or not (32 <= byte <= 126)):
                byte = extract_byte(conn, addr)
                attempts += 1

                if not (32 <= byte <= 126):
                    log.warning(f'Invalid byte {hex(byte)} at {addr}, retry {attempts}')
                    if attempts < 3:
                        conn = setup_connection()

            extracted.append(byte)
            log.success(f'Final byte: {hex(byte)} ({chr(byte)})')

            if not conn.connected():
                conn = setup_connection()

        extracted_str = ''.join(chr(b) for b in extracted)
        log.info(f'Extracted string: {extracted_str}')

        if extracted_str.startswith('flag{'):
            log.success(f'Found flag pattern: {extracted_str}')

    except Exception as e:
        log.error(f'Error during extraction: {str(e)}')
    finally:
        if conn and conn.connected():
            conn.close()

if __name__ == '__main__':
    main()

from pwn import *
import time
import statistics

# Enable debugging
context.log_level = 'debug'

def setup_connection():
    conn = remote('rev.chal.csaw.io', 8000)
    conn.recvuntil(b'WELCOME')
    return conn

def measure_timing(conn, address):
    start = time.time_ns()
    try:
        conn.sendline(f'r {address:x}'.encode())
        conn.recvuntil(b'\n', timeout=1)
        end = time.time_ns()
        return end - start
    except:
        return float('inf')

def flush_cache(conn):
    try:
        for addr in range(0, 0x100, 16):
            conn.sendline(f'r {addr:x}'.encode())
            conn.recvuntil(b'\n', timeout=1)
        time.sleep(0.1)
    except:
        pass

def train_branch(conn, num_iters=6):
    try:
        for _ in range(num_iters):
            conn.sendline(b'r 0')
            conn.recvuntil(b'\n', timeout=1)
    except:
        pass

def probe_cache_bit(conn, target_addr, bit_pos):
    total_timing = 0
    num_samples = 3
    valid_samples = 0

    while valid_samples < num_samples:
        try:
            # Train branch predictor
            train_branch(conn)

            # Trigger speculative execution
            conn.sendline(b'mode')
            conn.recvuntil(b'\n', timeout=1)

            # Access target memory and probe cache
            probe_addr = 0xFF
            timing = measure_timing(conn, probe_addr)

            if timing != float('inf'):
                total_timing += timing
                valid_samples += 1

            flush_cache(conn)

        except EOFError:
            conn = setup_connection()
            continue

    avg_timing = total_timing / num_samples
    return avg_timing < 200000  # Threshold for cache hit

def extract_byte(target_addr):
    result_byte = 0
    conn = setup_connection()

    try:
        # Get baseline timing
        baseline = measure_timing(conn, 0xFF)

        for bit in range(8):
            flush_cache(conn)
            is_set = probe_cache_bit(conn, target_addr, bit)
            if is_set:
                result_byte |= (1 << bit)

            # Reconnect occasionally to avoid timeouts
            if not conn.connected():
                conn = setup_connection()

        return result_byte
    except Exception as e:
        log.error(f"Error extracting byte: {str(e)}")
        return None
    finally:
        if conn and conn.connected():
            conn.close()

def main():
    flag_bytes = []

    try:
        # Try to extract first few bytes
        for addr in range(8):
            log.info(f"Attempting to extract byte at address {addr}")

            byte = None
            retries = 0

            while byte is None and retries < 3:
                byte = extract_byte(addr)
                retries += 1

            if byte is not None:
                flag_bytes.append(byte)
                log.success(f"Extracted byte {hex(byte)} ({chr(byte) if 32 <= byte <= 126 else '?'})")

                # Check for flag pattern
                if len(flag_bytes) >= 5:
                    try:
                        test_str = bytes(flag_bytes).decode('ascii', errors='ignore')
                        if 'flag{' in test_str:
                            log.success(f"Found flag pattern! {test_str}")
                            break
                    except:
                        pass

            time.sleep(0.5)  # Brief pause between bytes

        # Try to construct flag from extracted bytes
        if flag_bytes:
            try:
                flag_str = bytes(flag_bytes).decode('ascii', errors='ignore')
                log.info(f"Final extracted data: {flag_str}")
            except:
