class TimingCache:
    def __init__(self, size=256):
        self.size = size
        self.cache = [None] * size
        self.hits = [0] * size
        self.misses = [0] * size

    def access(self, addr, timing):
        self.cache[addr % self.size] = timing
        if timing < self.get_threshold(addr):
            self.hits[addr % self.size] += 1
        else:
            self.misses[addr % self.size] += 1

    def get_threshold(self, addr):
        idx = addr % self.size
        if self.cache[idx] is None:
            return float('inf')
        return self.cache[idx] * 0.9

    def get_hit_rate(self, addr):
        idx = addr % self.size
        total = self.hits[idx] + self.misses[idx]
        if total == 0:
            return 0.0
        return self.hits[idx] / total

