            time.sleep(0.05)
        return success >= iterations // 2

    def flush_cache(self):
        """Flush cache by reading multiple addresses"""
        for addr in [0x00, 0x40, 0x80, 0xC0]:
            if not self.send_cmd(f'r {addr:x}'.encode()):
                return False
            time.sleep(0.05)
        return True

    def measure_access(self, addr, retries=3):
        """Measure memory access time"""
        times = []
        for _ in range(retries):
            start = time.time_ns()
            resp = self.send_cmd(f'r {addr:x}'.encode())
            if resp is not None:
                end = time.time_ns()
                times.append(end - start)
            time.sleep(0.05)

        return statistics.median(times) if times else None

